from concurrent.futures import ThreadPoolExecutor
from glob import glob
from lxml import etree
from os import path
import os.path


def check_product(l2a_path):
    img_data_dirs = glob(os.path.join(l2a_path, "GRANULE/L2A*/IMG_DATA"))
    if not img_data_dirs:
        return False
    img_data_dir = img_data_dirs[0]

    # This isn't strictly required but make sure everything is there
    # And it's not just file listing that fails, reading can also trigger the problem
    glob(path.join(img_data_dir, "R10m/*_B*_10m.jp2"))
    glob(path.join(img_data_dir, "R20m/*_B*_20m.jp2"))

    # metadata = path.join(l2a_path, "MTD_MSIL2A.xml")
    # parser = etree.XMLPullParser(["start"])
    # with open(metadata, "r") as file:
    #     parser.feed(file.read())
    # for event, elem in parser.read_events():
    #     if elem.tag == "BOA_ADD_OFFSET":
    #         # store the offset, we'll need it later
    #         pass
    return True

def run():
    products = get_products()

    # crashes eodata
    # for product in products:
    #     if not check_product(product):
    #         print(f"Can't read {product}")

    # still crashes eodata, but faster
    with ThreadPoolExecutor(max_workers=4) as executor:
        for (p, ok) in executor.map(lambda p: (p, check_product(p)), products):
            if not ok:
                print(f"Can't read {p}")

